function utf8ToBase64(e){var t=(new TextEncoder).encode(e);let o="";for(let e=0;e<t.length;e++)o+=String.fromCharCode(t[e]);return btoa(o)}function base64ToUtf8(e){var t=atob(e),o=new Uint8Array(t.length);for(let e=0;e<t.length;e++)o[e]=t.charCodeAt(e);return(new TextDecoder).decode(o)}document.addEventListener("submit",function(e){if(e.target&&"reply-form"===e.target.id){e.preventDefault();e=document.getElementById("reply-message").value;if(e){e=utf8ToBase64(e);try{fetch(BASE_URL+"/api/postdisc",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({cookie:getcookie(),cid:discussionId,content:e})}).then(e=>e.json()).then(e=>{"Y"===e.status?window.location.reload():alert("回复失败")})}catch(e){console.error("提交回复时出错:",e)}}else alert("回复内容不能为空")}});